# Helpers

def norm(s: str) -> str:
    return re.sub(r'\s+', ' ', s.strip()).lower()

def split_artists(artists_str: str):
    return [a.strip() for a in artists_str.split(',') if a.strip()] if artists_str else []

def artist_set_from_artists_str(artists_str: str):
    return set(norm(a) for a in split_artists(artists_str))

def artist_set_from_result(result):
    return set(norm(a['name']) for a in result.get('artists',[]) if 'name' in a)

# Matching functions (same as earlier, robust)

def find_best_song(song_title, desired_artists_str, page_limit=20):
    desired_list = split_artists(desired_artists_str)
    desired_set = set(norm(a) for a in desired_list)
    first_artist = desired_list[0] if desired_list else ''
    query = f"{song_title} {first_artist}".strip()

    all_results=[]
    page_index=0
    while True:
        res = apis.spotify.search_songs(query=query, page_index=page_index, page_limit=page_limit)
        if not res:
            break
        all_results.extend(res)
        if len(res) < page_limit:
            break
        page_index += 1

    exact_title = [r for r in all_results if norm(r.get('title',''))==norm(song_title)]
    subset_cands=[]
    if desired_set:
        for r in exact_title:
            cand_set = artist_set_from_result(r)
            if desired_set.issubset(cand_set):
                subset_cands.append(r)

    chosen=None
    if desired_set and len(subset_cands)==1:
        chosen=subset_cands[0]
        reason='unique subset artist match'
    elif desired_set and len(subset_cands)>1:
        extras_sorted = sorted(subset_cands, key=lambda r: len(artist_set_from_result(r)-desired_set))
        best_extra = len(artist_set_from_result(extras_sorted[0])-desired_set)
        bests = [r for r in subset_cands if len(artist_set_from_result(r)-desired_set)==best_extra]
        chosen=bests[0]
        reason='subset match with minimal extra artists'
    else:
        # fallback title-only unique
        if len(exact_title)==1:
            chosen=exact_title[0]
            reason='unique exact title match'
        elif len(exact_title)>1:
            # score by minimal missing then extra
            if desired_set:
                scored=[]
                for r in exact_title:
                    cand_set=artist_set_from_result(r)
                    missing_size=len(desired_set-cand_set)
                    extra_size=len(cand_set-desired_set)
                    scored.append((missing_size, extra_size, -r.get('play_count',0), r))
                scored.sort(key=lambda x:(x[0],x[1],x[2]))
                chosen=scored[0][3]
                reason='best approximate match minimal missing/extra'
            else:
                chosen=exact_title[0]
                reason='ambiguous title-only; chose first'
        else:
            chosen=None
            reason='no match'

    return chosen, {'query': query, 'reason': reason}

